window.EP = {"name": "ch5", "label": "एपिसोड 5", "en": "Five Pieces of a God", "duration": 1113.73, "title": [{"start": 5.5, "end": 6.88, "text": "हिडन उत्तराखंड"}, {"start": 7.43, "end": 10.18, "text": "अ बुक बाय, पार्थ डी. जोशी"}, {"start": 10.73, "end": 13.99, "text": "चैप्टर फ़ाइव। फ़ाइव पीसेज़ ऑफ़ अ गॉड"}, {"start": 14.54, "end": 19.31, "text": "डे फ़ाइव। चोपता, तुंगनाथ, चंद्रशिला"}], "captions": [{"start": 20.86, "end": 23.98, "text": "मैं उस रात को ठीक से डिस्क्राइब नहीं करूँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 23.98, "end": 27.18, "text": "कर नहीं सकता, और आपको उसकी ज़रूरत भी नहीं है।", "who": "", "voice": "narrator", "diary": false}, {"start": 27.63, "end": 30.45, "text": "हमने आधी रात तक टॉर्च लेकर सड़क छानी।", "who": "", "voice": "narrator", "diary": false}, {"start": 30.45, "end": 34.1, "text": "गब्बर ने आधा गाँव जगा दिया, दरवाज़े खटखटाते हुए,", "who": "", "voice": "narrator", "diary": false}, {"start": 34.1, "end": 36.01, "text": "गढ़वाली में चिल्लाते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 36.01, "end": 39.74, "text": "शाओनी ने पुलिस को फ़ोन किया, और पुलिस ने वही कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 39.74, "end": 48.2, "text": "जो पुलिस किसी तीर्थ-नगर में तीन घंटे से गायब किसी बीस-बाईस साल के लड़के के बारे में कहती है: सुबह तक देखते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 48.2, "end": 50.63, "text": "साहब, शायद कहीं चाय पी रहा होगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 50.63, "end": 54.37, "text": "शाओनी ने फ़ोन पर उस आदमी को, बहुत साफ़ हिंदी में,", "who": "", "voice": "narrator", "diary": false}, {"start": 54.37, "end": 58.18, "text": "ठीक-ठीक बता दिया, कि वो उस बारे में क्या सोचती है।", "who": "", "voice": "narrator", "diary": false}, {"start": 58.18, "end": 61.83, "text": "मैंने उसे पहले कभी आवाज़ ऊँची करते नहीं सुना था।", "who": "", "voice": "narrator", "diary": false}, {"start": 61.83, "end": 64.5, "text": "उम्मीद है, दोबारा कभी नहीं सुनूँगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 64.95, "end": 68.73, "text": "मैं उसी बेंच पर बैठा, जहाँ क्षितिज की डायरी पड़ी थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 68.73, "end": 70.62, "text": "उसे दोनों हाथों में पकड़े,", "who": "", "voice": "narrator", "diary": false}, {"start": 70.62, "end": 73.38, "text": "और वो एक काम किया, जो मुझे काम का लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 73.38, "end": 74.77, "text": "मैंने प्रार्थना की।", "who": "", "voice": "narrator", "diary": false}, {"start": 74.77, "end": 76.0, "text": "पोलाइट वाली नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 76.0, "end": 78.69, "text": "वो वाली, जिसमें आप ऐसे वादे करते हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 78.69, "end": 82.33, "text": "जिनके बारे में आपको यक़ीन नहीं, कि आप निभा पाएँगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 82.78, "end": 87.13, "text": "सुबह पाँच बजकर बावन मिनट पर, मेरा फ़ोन बजा।", "who": "", "voice": "narrator", "diary": false}, {"start": 87.13, "end": 88.24, "text": "अननोन नंबर।", "who": "", "voice": "narrator", "diary": false}, {"start": 88.69, "end": 89.38, "text": "एक फ़ोटो।", "who": "", "voice": "narrator", "diary": false}, {"start": 89.38, "end": 95.4, "text": "क्षितिज, किसी सड़क किनारे वाले ढाबे के बाहर एक प्लास्टिक की कुर्सी पर बैठा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 95.4, "end": 97.99, "text": "कंबल में लिपटा, हाथ में चाय का कप।", "who": "", "voice": "narrator", "diary": false}, {"start": 97.99, "end": 98.91, "text": "बिना चोट के।", "who": "", "voice": "narrator", "diary": false}, {"start": 98.91, "end": 99.67, "text": "चिढ़ा हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 99.67, "end": 100.21, "text": "ज़िंदा।", "who": "", "voice": "narrator", "diary": false}, {"start": 100.91, "end": 101.45, "text": "नीचे:", "who": "", "voice": "narrator", "diary": false}, {"start": 102.15, "end": 102.69, "text": "चोपता।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 102.69, "end": 103.32, "text": "दस बजे।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 103.32, "end": 104.49, "text": "ढाबे के बाहर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 104.49, "end": 105.66, "text": "लड़का ठीक है।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 105.66, "end": 108.27, "text": "हम जानवर नहीं हैं, प्रोफ़ेसर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 108.27, "end": 108.54, "text": "आर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 108.99, "end": 113.35, "text": "शाओनी ने मेरे कंधे के ऊपर से पढ़ा, और अचानक बेंच पर बैठ गई,", "who": "", "voice": "narrator", "diary": false}, {"start": 113.35, "end": 116.46, "text": "जैसे किसी ने उसकी टाँगों की डोर काट दी हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 117.16, "end": 118.58, "text": "फिर वो दोबारा खड़ी हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 119.28, "end": 119.66, "text": "चलो।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 119.86, "end": 122.9, "text": "उसने गब्बर से कहा, जिसके हाथ में चाबियाँ पहले से थीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 124.4, "end": 129.9, "text": "चोपता एक पहाड़ी पर बसा एक मैदान है, बुरांस और बाँज के जंगलों से घिरा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 129.9, "end": 134.58, "text": "और पूरा हिमालय क्षितिज पर ऐसे लाइन में खड़ा है, जैसे कोई जूरी।", "who": "", "voice": "narrator", "diary": false}, {"start": 134.58, "end": 138.87, "text": "लोग कहते हैं, बसंत में ये गढ़वाल की सबसे ख़ूबसूरत जगह है।", "who": "", "voice": "narrator", "diary": false}, {"start": 138.87, "end": 142.49, "text": "अक्टूबर के आख़िर में, सुबह नौ बजकर पचास मिनट पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 142.49, "end": 150.48, "text": "जब मेरा दिल नवरात्रि की आख़िरी रात के किसी गरबा ढोली की तरह धड़क रहा था… मैंने एक भी पेड़ नोटिस नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 150.93, "end": 155.78, "text": "क्षितिज ढाबे के बाहर बिल्कुल वैसे ही बैठा था, जैसे फ़ोटो में।", "who": "", "voice": "narrator", "diary": false}, {"start": 155.78, "end": 156.18, "text": "कंबल।", "who": "", "voice": "narrator", "diary": false}, {"start": 156.18, "end": 156.5, "text": "चाय।", "who": "", "voice": "narrator", "diary": false}, {"start": 156.5, "end": 163.81, "text": "आस-पास और कोई नहीं, सिवाय मालिक के, जिसे साफ़ तौर पर कोई अंदाज़ा नहीं था कि कुछ अजीब हुआ है,", "who": "", "voice": "narrator", "diary": false}, {"start": 163.81, "end": 168.03, "text": "और जो जानना चाहता था कि हमें आलू पराठे चाहिए या नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 168.48, "end": 170.3, "text": "शाओनी सबसे पहले उस तक पहुँची।", "who": "", "voice": "narrator", "diary": false}, {"start": 170.3, "end": 171.99, "text": "वो हिस्सा मैं छोड़ रहा हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 171.99, "end": 173.12, "text": "वो उन दोनों का है।", "who": "", "voice": "narrator", "diary": false}, {"start": 173.57, "end": 176.69, "text": "जब मैं उन तक पहुँचा, क्षितिज ने मेरी तरफ़ देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 176.69, "end": 178.28, "text": "और बिल्कुल सीरियसली कहा:", "who": "", "voice": "narrator", "diary": false}, {"start": 178.73, "end": 179.17, "text": "भाई।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 179.17, "end": 180.37, "text": "मेरी डायरी?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 180.82, "end": 181.96, "text": "मैंने उसे दे दी।", "who": "", "voice": "narrator", "diary": false}, {"start": 181.96, "end": 185.31, "text": "उसने एक सेकंड के लिए उसे दोनों हाथों में पकड़ा,", "who": "", "voice": "narrator", "diary": false}, {"start": 185.31, "end": 188.88, "text": "जैसे कोई ऐसी चीज़ पकड़ता है, जो मौत से वापस आई हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 188.88, "end": 194.52, "text": "फिर वो नीचे झुका, अपना बायाँ जूता उतारा, मोज़ा उतारा, और उसमें से एक मुड़ा हुआ,", "who": "", "voice": "narrator", "diary": false}, {"start": 194.52, "end": 197.45, "text": "पसीने से भीगा पेट्रोल पंप का रसीद निकाला,", "who": "", "voice": "narrator", "diary": false}, {"start": 197.45, "end": 200.66, "text": "जिसके दोनों तरफ़ बहुत छोटी लिखावट भरी हुई थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 201.11, "end": 202.49, "text": "उन्होंने मेरी डायरी नहीं ली।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 202.69, "end": 203.94, "text": "उसने मुझसे कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 204.14, "end": 205.02, "text": "तो मैंने नई बना ली।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 205.47, "end": 207.11, "text": "मैंने बारह साल पढ़ाया है।", "who": "", "voice": "narrator", "diary": false}, {"start": 207.11, "end": 209.6, "text": "सैकड़ों प्रोजेक्ट्स सुपरवाइज़ किए हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 209.6, "end": 210.72, "text": "मुझे कभी, कभी भी,", "who": "", "voice": "narrator", "diary": false}, {"start": 210.72, "end": 215.7, "text": "किसी स्टूडेंट पर इससे ज़्यादा गर्व नहीं हुआ… और वो मेरा स्टूडेंट है भी नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 217.2, "end": 224.04, "text": "हमने उसे ढाबे की इकलौती टेबल पर बिठाया, शाओनी ने बिना पूछे उसके लिए तीन पराठे ऑर्डर किए,", "who": "", "voice": "narrator", "diary": false}, {"start": 224.04, "end": 228.24, "text": "और क्षितिज ने रसीद से पढ़कर हमें बताया कि क्या हुआ था।", "who": "", "voice": "narrator", "diary": false}, {"start": 228.69, "end": 231.53, "text": "दो आदमियों ने उसे बेंच से उठा लिया था।", "who": "", "voice": "narrator", "diary": false}, {"start": 231.53, "end": 234.53, "text": "ज़बरदस्ती नहीं, उसने बताया; प्रोफ़ेशनली,", "who": "", "voice": "narrator", "diary": false}, {"start": 234.53, "end": 239.1, "text": "जैसे पैकर्स किसी सोफ़े को उठाते हैं, जिसकी उन्हें परवाह न हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 239.1, "end": 242.54, "text": "उन्होंने उसे एक डार्क एस-यू-वी के पीछे बिठाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 242.54, "end": 247.19, "text": "और लगभग दो घंटे गाड़ी चलाई, घाटी में ऊपर, और एक पहाड़ी के पार।", "who": "", "voice": "narrator", "diary": false}, {"start": 247.19, "end": 249.66, "text": "भल्ला आगे पैसेंजर सीट पर बैठा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 249.66, "end": 251.76, "text": "दूसरा आदमी गाड़ी चला रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 251.76, "end": 253.93, "text": "किसी ने उसे चोट नहीं पहुँचाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 254.38, "end": 259.63, "text": "फिर, अँधेरे में एक ढाबे पर, ड्राइवर ने एक फ़ोन स्पीकर पर रखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 259.63, "end": 262.13, "text": "और उसमें से रोहन की आवाज़ आई।", "who": "", "voice": "narrator", "diary": false}, {"start": 262.58, "end": 263.63, "text": "वो पोलाइट था।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 263.83, "end": 264.69, "text": "क्षितिज ने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 264.89, "end": 266.65, "text": "हमेशा पोलाइट होता है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 266.65, "end": 269.92, "text": "उसने पूछा, केदारनाथ में हमें क्या मिला।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 270.37, "end": 271.07, "text": "तुमने क्या बोला?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 271.27, "end": 272.46, "text": "शाओनी ने उससे पूछा।", "who": "", "voice": "narrator", "diary": false}, {"start": 272.91, "end": 274.36, "text": "मैंने कहा, दर्शन।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 274.36, "end": 275.56, "text": "कुछ नहीं मिला।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 275.56, "end": 276.67, "text": "सिर्फ़ दर्शन।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 276.67, "end": 280.52, "text": "और भीम शिला देख के मैं बहुत इमोशनल हो गया था।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 280.97, "end": 282.31, "text": "मैं लगभग हँस पड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 282.51, "end": 283.31, "text": "उसने माना?", "who": "", "voice": "narrator", "diary": false}, {"start": 283.76, "end": 284.22, "text": "नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 284.42, "end": 285.93, "text": "क्षितिज ने कंधे उचकाए।", "who": "", "voice": "narrator", "diary": false}, {"start": 286.13, "end": 287.89, "text": "पर उसने मुझे चाय पिलाई,", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 287.89, "end": 291.41, "text": "और बोला: प्रोफ़ेसर को बोलो, औली में मिलते हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 291.41, "end": 292.49, "text": "नोटबुक के साथ।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 292.49, "end": 292.95, "text": "अकेले।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 292.95, "end": 293.56, "text": "संडे को।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 293.56, "end": 295.17, "text": "हम सब समझदार लोग हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 295.62, "end": 296.96, "text": "फिर वो उसे यहाँ ले आए,", "who": "", "voice": "narrator", "diary": false}, {"start": 296.96, "end": 300.49, "text": "सुबह होते ही एक कंबल के साथ छोड़ गए… और चाय के पैसे दे गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 300.94, "end": 303.38, "text": "उसने रसीद हमारे बीच टेबल पर फैलाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 303.38, "end": 307.25, "text": "उस पर, इतनी छोटी लिखावट में, कि मुझे चश्मा लगाना पड़ा:", "who": "", "voice": "narrator", "diary": false}, {"start": 307.7, "end": 310.53, "text": "एस-यू-वी का नंबर प्लेट, उल्टा लिखा हुआ,", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 310.53, "end": 313.73, "text": "ताकि अगर किसी को मिले, तो बस कोई गिचपिच लगे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 314.18, "end": 316.57, "text": "बूट्स: भल्ला वाला ही ब्रैंड।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 316.57, "end": 317.67, "text": "वही ग्रे गाद।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 318.12, "end": 321.61, "text": "ड्राइवर ने फ़ोन पर कहा, जोशीमठ पंप पे डीज़ल।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 321.61, "end": 323.91, "text": "जोशीमठ: औली के नीचे वाला शहर।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 324.36, "end": 325.86, "text": "भल्ला सोता नहीं है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 325.86, "end": 328.56, "text": "बार-बार पीछे वाली खिड़की देखता है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 328.56, "end": 329.98, "text": "अँधेरे से डरता है?", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 330.43, "end": 333.09, "text": "ड्राइवर ने पुराने पहाड़ी गाने लगाए।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 333.09, "end": 334.6, "text": "भल्ला ने बंद कर दिए।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 334.6, "end": 335.13, "text": "दो बार।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 335.13, "end": 337.41, "text": "दूसरी बार उसने कहा, गाना नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 337.41, "end": 338.17, "text": "बहुत धीरे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 338.17, "end": 339.38, "text": "गुस्से में नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 339.38, "end": 340.75, "text": "जैसे… दर्द हुआ हो।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 341.45, "end": 343.23, "text": "ये लोग बहुत बातें करते हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 343.93, "end": 346.97, "text": "और सबसे नीचे, गोला बनाकर:", "who": "", "voice": "narrator", "diary": false}, {"start": 347.67, "end": 349.15, "text": "रेटिंग: तीन स्टार।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 349.15, "end": 350.22, "text": "चाय अच्छी थी।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 350.22, "end": 351.86, "text": "बहुत बातें करते हैं।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 352.31, "end": 356.88, "text": "शाओनी ने आख़िरी लाइन पढ़ी और हँस पड़ी, चौदह घंटों में पहली असली हँसी,", "who": "", "voice": "narrator", "diary": false}, {"start": 356.88, "end": 358.87, "text": "फिर थोड़ा रोई, फिर ऐसे दिखाया,", "who": "", "voice": "narrator", "diary": false}, {"start": 358.87, "end": 361.33, "text": "जैसे उसने दोनों में से कुछ नहीं किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 361.78, "end": 370.09, "text": "बाद में, जब वो पराठों की क़ीमत पर ढाबे वाले से बहस करने चली गई, जो इस बात का साइन था कि वो पूरी तरह ठीक हो चुकी है,", "who": "", "voice": "narrator", "diary": false}, {"start": 370.09, "end": 373.41, "text": "मैं क्षितिज के बग़ल में बैठा, और वो सवाल पूछा,", "who": "", "voice": "narrator", "diary": false}, {"start": 373.41, "end": 375.36, "text": "जो किसी और ने नहीं पूछा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 375.81, "end": 376.37, "text": "डर लगा?", "who": "", "voice": "narrator", "diary": false}, {"start": 376.82, "end": 379.22, "text": "उसने बहुत देर तक अपनी रसीद को देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 379.67, "end": 379.99, "text": "हाँ।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 380.19, "end": 381.06, "text": "उसने मुझसे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 381.26, "end": 381.62, "text": "बहुत।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 381.62, "end": 383.78, "text": "पहले घंटे में हाथ काँप रहे थे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 383.78, "end": 386.37, "text": "फिर मैंने सोचा: अगर मैं लिख रहा हूँ,", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 386.37, "end": 390.11, "text": "तो मैं सिर्फ़ एक लड़का नहीं हूँ, जिसको उठा लिया गया।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 390.11, "end": 392.77, "text": "मैं एक लड़का हूँ, जो नोट्स ले रहा है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 392.97, "end": 395.53, "text": "उसने रसीद को उसकी तहों पर, सावधानी से मोड़ा।", "who": "", "voice": "narrator", "diary": false}, {"start": 395.73, "end": 396.83, "text": "डर वही है, भाई।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 396.83, "end": 398.66, "text": "… बस उसको एक काम दे दिया।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 399.11, "end": 402.28, "text": "मैंने हिम्मत के बारे में बहुत सारी किताबें पढ़ी हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 402.28, "end": 408.32, "text": "ये उसकी सबसे अच्छी डेफ़िनिशन है, जो मुझे कभी मिली… और वो एक पेट्रोल पंप की रसीद के पीछे लिखी गई थी,", "who": "", "voice": "narrator", "diary": false}, {"start": 408.32, "end": 410.95, "text": "एक ऐसे लड़के ने, जिसने एक ही मोज़ा पहना था।", "who": "", "voice": "narrator", "diary": false}, {"start": 412.45, "end": 416.8, "text": "ग्यारह बजे, डैशबोर्ड पर रिंग लाइट लगाए एक सफ़ेद एस-यू-वी,", "who": "", "voice": "narrator", "diary": false}, {"start": 416.8, "end": 419.55, "text": "चोपता वाली सड़क पर उछलती हुई ऊपर आई,", "who": "", "voice": "narrator", "diary": false}, {"start": 419.55, "end": 422.9, "text": "और लाल कीचड़ उड़ाती हुई हमारे बग़ल में रुकी।", "who": "", "voice": "narrator", "diary": false}, {"start": 423.35, "end": 427.67, "text": "गोलू कूदकर बाहर आया, घुटनों तक कीचड़ में सना, पहले से बोलता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 427.87, "end": 428.94, "text": "घोस्ट फ़ैमिली!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 428.94, "end": 431.3, "text": "रात भर तुंगनाथ के भूत को ढूँढा!", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 431.3, "end": 434.74, "text": "कुछ नहीं मिला, पर मेरा जी-पी-एस भी खो गया था…", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 435.19, "end": 438.63, "text": "शाओनी बेंच पर मुड़ी, और उसे देखा।", "who": "", "voice": "narrator", "diary": false}, {"start": 439.08, "end": 442.86, "text": "मैंने आपको शाओनी के लुक्स के बारे में बताया है।", "who": "", "voice": "narrator", "diary": false}, {"start": 442.86, "end": 444.23, "text": "ये एक नया लुक था।", "who": "", "voice": "narrator", "diary": false}, {"start": 444.23, "end": 448.58, "text": "उसने उसकी कीचड़ से सनी गाड़ी, उसकी थकी हुई, लाल आँखें,", "who": "", "voice": "narrator", "diary": false}, {"start": 448.58, "end": 453.02, "text": "और उसकी कहानी को उठाया… और चुपचाप एक तराज़ू पर रख दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 453.47, "end": 455.34, "text": "तुंगनाथ का भूत।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 455.54, "end": 456.41, "text": "उसने दोहराया।", "who": "", "voice": "narrator", "diary": false}, {"start": 456.61, "end": 457.7, "text": "रात भर।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 458.15, "end": 459.13, "text": "हाँ, दीदी…", "who": "गोलू", "voice": "golu", "diary": false}, {"start": 459.58, "end": 462.44, "text": "तुंगनाथ का रास्ता चोपता से है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 462.44, "end": 463.48, "text": "इसी रोड से।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 463.68, "end": 466.31, "text": "उसने पहाड़ी से नीचे इशारा किया, फिर ऊपर।", "who": "", "voice": "narrator", "diary": false}, {"start": 466.51, "end": 467.81, "text": "हम सुबह से यहाँ बैठे हैं।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 467.81, "end": 469.68, "text": "तुम्हारी गाड़ी ऊपर से नहीं आई, गोलू।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 469.68, "end": 470.36, "text": "… नीचे से आई।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 470.81, "end": 472.08, "text": "गोलू ने मुँह खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 472.08, "end": 472.72, "text": "बंद किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 472.72, "end": 478.94, "text": "फिर वो अपनी लाउड यूट्यूब वाली हँसी हँसा, ख़राब नेटवर्क और ग़लत मोड़ के बारे में कुछ कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 478.94, "end": 481.85, "text": "और ढाबे के कुत्ते को फ़िल्म करने चला गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 482.3, "end": 484.65, "text": "क्षितिज पहले ही लिख चुका था।", "who": "", "voice": "narrator", "diary": false}, {"start": 484.65, "end": 487.68, "text": "उसने डायरी घुमाई, ताकि मैं पढ़ सकूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 487.68, "end": 490.46, "text": "गोलू: गाड़ी पर कीचड़, लाल मिट्टी।", "who": "", "voice": "narrator", "diary": false}, {"start": 490.46, "end": 493.92, "text": "उसी रंग की, जिस सड़क से वो मुझे ले गए थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 494.37, "end": 496.85, "text": "अगली बात किसी ने ज़ोर से नहीं कही।", "who": "", "voice": "narrator", "diary": false}, {"start": 496.85, "end": 499.05, "text": "हम सबके दिमाग़ में थी, फिर भी।", "who": "", "voice": "narrator", "diary": false}, {"start": 500.55, "end": 502.15, "text": "संडे में दो दिन थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 502.15, "end": 505.95, "text": "शाओनी सीधे जोशीमठ पुलिस के पास जाना चाहती थी।", "who": "", "voice": "narrator", "diary": false}, {"start": 505.95, "end": 511.1, "text": "गब्बर घर जाकर ऐसे दिखाना चाहता था, जैसे ये सब हो ही नहीं रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 511.1, "end": 514.39, "text": "मैं कहीं ऊँचाई पर बैठकर सोचना चाहता था।", "who": "", "voice": "narrator", "diary": false}, {"start": 514.84, "end": 516.19, "text": "ये क्षितिज ने तय किया,", "who": "", "voice": "narrator", "diary": false}, {"start": 516.19, "end": 518.84, "text": "मैदान के ऊपर वाली पहाड़ी की तरफ़ देखते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 519.29, "end": 520.25, "text": "तुंगनाथ।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 520.45, "end": 521.09, "text": "उसने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 521.29, "end": 521.71, "text": "ऊपर।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 521.71, "end": 523.69, "text": "जहाँ कोई नहीं आएगा।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 523.69, "end": 524.84, "text": "हम सोचेंगे।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 525.54, "end": 527.59, "text": "तो दोपहर में, हम चढ़े।", "who": "", "voice": "narrator", "diary": false}, {"start": 528.29, "end": 531.54, "text": "चोपता से तुंगनाथ का रास्ता खड़ी चढ़ाई वाला है,", "who": "", "voice": "narrator", "diary": false}, {"start": 531.54, "end": 535.5, "text": "पत्थर बिछा हुआ, और उसे आपकी फ़ीलिंग्स की कोई परवाह नहीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 535.5, "end": 538.75, "text": "तुंगनाथ मंदिर लगभग छत्तीस सौ अस्सी मीटर पर है।", "who": "", "voice": "narrator", "diary": false}, {"start": 538.95, "end": 541.27, "text": "दुनिया का सबसे ऊँचा शिव मंदिर।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 541.47, "end": 546.69, "text": "गब्बर ने हम तीनों को गर्व से बताया, जैसे उसने ख़ुद बनाया हो।", "who": "", "voice": "narrator", "diary": false}, {"start": 546.69, "end": 552.27, "text": "ये एक छोटा, अँधेरा, प्राचीन मंदिर है, तीन तरफ़ बर्फ़ीली चोटियाँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 552.27, "end": 556.01, "text": "और आसमान इतना पास, कि लगे, लाठी से छू लोगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 556.46, "end": 561.64, "text": "मंदिर की सीढ़ियों पर, गब्बर ने हमें बताया, कि ये यहाँ क्यों है।", "who": "", "voice": "narrator", "diary": false}, {"start": 561.64, "end": 566.16, "text": "इस बार मैंने बस सुना, क्योंकि ये उन कहानियों में से है,", "who": "", "voice": "narrator", "diary": false}, {"start": 566.16, "end": 570.02, "text": "जो आपको उसी जगह पर सुननी चाहिए, जहाँ की वो हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 570.47, "end": 574.81, "text": "महाभारत के महायुद्ध के बाद, उसने बताया, पांडव हिमालय आए,", "who": "", "voice": "narrator", "diary": false}, {"start": 574.81, "end": 578.83, "text": "अपने ही परिवार वालों को मारने के पाप से मुक्ति पाने।", "who": "", "voice": "narrator", "diary": false}, {"start": 578.83, "end": 580.77, "text": "वो शिव से माफ़ी चाहते थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 580.77, "end": 583.02, "text": "शिव माफ़ी नहीं देना चाहते थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 583.02, "end": 586.66, "text": "तो वो उनसे छिप गए: उन्होंने एक बैल का रूप लिया,", "who": "", "voice": "narrator", "diary": false}, {"start": 586.66, "end": 589.91, "text": "और इन पहाड़ों में चरते एक झुंड में मिल गए।", "who": "", "voice": "narrator", "diary": false}, {"start": 590.36, "end": 592.53, "text": "भीम ने उन्हें ढूँढ लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 592.53, "end": 596.24, "text": "भीम ने ही, ज़ाहिर है, जो सबसे ताक़तवर था।", "who": "", "voice": "narrator", "diary": false}, {"start": 596.24, "end": 602.03, "text": "वो एक घाटी के ऊपर टाँगें फैलाकर खड़े हो गए, एक पैर एक पहाड़ी पर,", "who": "", "voice": "narrator", "diary": false}, {"start": 602.03, "end": 606.83, "text": "दूसरा दूसरी पर, और झुंड को अपने नीचे से गुज़रने दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 606.83, "end": 609.0, "text": "हर बैल नीचे से निकल गया।", "who": "", "voice": "narrator", "diary": false}, {"start": 609.0, "end": 610.99, "text": "एक बैल ने मना कर दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 611.44, "end": 615.2, "text": "जब भीम ने उसे पकड़ा, तो बैल धरती में धँसने लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 615.2, "end": 620.4, "text": "भीम ने उसकी पीठ पकड़े रखी, और भगवान ग़ायब हो गए… लेकिन उनका शरीर,", "who": "", "voice": "narrator", "diary": false}, {"start": 620.4, "end": 623.76, "text": "गढ़वाल हिमालय में पाँच जगहों पर प्रकट हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 624.21, "end": 625.56, "text": "कूबड़ केदारनाथ में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 625.76, "end": 627.19, "text": "गब्बर ने उँगलियों पर गिना।", "who": "", "voice": "narrator", "diary": false}, {"start": 627.39, "end": 630.49, "text": "भुजाएँ यहाँ, तुंगनाथ में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 630.49, "end": 632.6, "text": "मुख रुद्रनाथ में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 632.6, "end": 635.2, "text": "नाभि मध्यमहेश्वर में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 635.2, "end": 637.68, "text": "जटाएँ कल्पेश्वर में।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 638.13, "end": 638.92, "text": "पंच केदार।", "who": "", "voice": "narrator", "diary": false}, {"start": 638.92, "end": 643.9, "text": "एक भगवान के पाँच टुकड़े, पहाड़ों में बिखरे हुए… और तीर्थयात्री,", "who": "", "voice": "narrator", "diary": false}, {"start": 643.9, "end": 646.03, "text": "जो पाँचों तक पैदल जाते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 646.48, "end": 648.41, "text": "तो हर जगह थोड़ा सा भगवान है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 648.61, "end": 650.21, "text": "क्षितिज ने लिखते हुए कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 650.66, "end": 653.51, "text": "पहाड़ में हर जगह थोड़ा सा भगवान है, बेटा।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 653.71, "end": 654.83, "text": "गब्बर ने उससे कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 655.03, "end": 657.51, "text": "बस पंच केदार में… एड्रेस लिखा है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 657.96, "end": 659.69, "text": "वो लाइन मैंने ख़ुद लिख ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 659.69, "end": 662.63, "text": "कुछ लाइनें आप अपने ड्राइवर से चुरा लेते हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 663.08, "end": 667.61, "text": "दूर नीचे, घाटी की ढलान पर बसे एक गाँव में, ढोल बजने लगे।", "who": "", "voice": "narrator", "diary": false}, {"start": 667.61, "end": 671.58, "text": "मंदिर का ढोल नहीं: ढोल और दमाऊ, रिहर्सल करते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 672.03, "end": 674.03, "text": "गब्बर ने सुनने के लिए सिर झुकाया।", "who": "", "voice": "narrator", "diary": false}, {"start": 674.23, "end": 675.89, "text": "पांडव लीला।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 676.09, "end": 677.19, "text": "उसने हमें बताया।", "who": "", "voice": "narrator", "diary": false}, {"start": 677.39, "end": 679.9, "text": "सर्दियों में शुरू होती है।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 679.9, "end": 682.59, "text": "गाँव वाले महाभारत खेलते हैं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 682.59, "end": 683.65, "text": "रात रात भर।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 683.85, "end": 686.73, "text": "वो रुका, शब्द सावधानी से चुनते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 686.93, "end": 690.25, "text": "और कभी कभी, जो भीम बनता है… उस पे सच में भीम आ जाते हैं।", "who": "गब्बर", "voice": "gabbar", "diary": false}, {"start": 690.7, "end": 695.46, "text": "मैं ठंडी हवा में ऊपर आते ढोल सुनता रहा, और सोचता रहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 695.46, "end": 698.6, "text": "कि इन पहाड़ों में कितने तरीक़े हैं,", "who": "", "voice": "narrator", "diary": false}, {"start": 698.6, "end": 702.45, "text": "किसी पुरानी चीज़ के वर्तमान में लौट आने के।", "who": "", "voice": "narrator", "diary": false}, {"start": 702.45, "end": 705.05, "text": "बाढ़ के बाद अपडेट हुआ एक गीत।", "who": "", "voice": "narrator", "diary": false}, {"start": 705.05, "end": 708.19, "text": "किसी पुरोहित के रजिस्टर में एक नाम।", "who": "", "voice": "narrator", "diary": false}, {"start": 708.19, "end": 710.53, "text": "पाँच टुकड़ों में एक भगवान।", "who": "", "voice": "narrator", "diary": false}, {"start": 710.53, "end": 715.82, "text": "एक हीरो, जो हर सर्दी किसी गाँव वाले के शरीर में लौट आता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 716.52, "end": 718.92, "text": "और बर्फ़ में… एक गरम पत्थर।", "who": "", "voice": "narrator", "diary": false}, {"start": 720.42, "end": 728.71, "text": "सूरज ढलते वक़्त, हम आख़िरी हिस्सा चढ़कर चंद्रशिला गए: तुंगनाथ के ऊपर की चोटी, जहाँ नंदा देवी,", "who": "", "voice": "narrator", "diary": false}, {"start": 728.71, "end": 731.92, "text": "त्रिशूल, चौखंबा और केदार की चोटियाँ,", "who": "", "voice": "narrator", "diary": false}, {"start": 731.92, "end": 735.31, "text": "सब सोने में एक लाइन में खड़ी होती हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 735.31, "end": 736.83, "text": "हम अकेले नहीं थे।", "who": "", "voice": "narrator", "diary": false}, {"start": 736.83, "end": 744.14, "text": "चोटी पर, एक पत्थर पर, एक बूढ़ा आदमी बैठा था, आर्मी-सरप्लस वाली एक जैकेट में लिपटा,", "who": "", "voice": "narrator", "diary": false}, {"start": 744.14, "end": 748.06, "text": "जो इतनी फीकी थी कि उसका कोई रंग नहीं बचा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 748.06, "end": 750.56, "text": "एक फ़्लास्क से चाय पीता हुआ।", "who": "", "voice": "narrator", "diary": false}, {"start": 751.01, "end": 754.25, "text": "उसने बिना कुछ कहे, फ़्लास्क हमारी तरफ़ बढ़ा दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 754.25, "end": 757.17, "text": "पहाड़ में, कोई न कोई हमेशा चाय ऑफ़र करता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 757.62, "end": 759.06, "text": "उसका नाम दोरजे था।", "who": "", "voice": "narrator", "diary": false}, {"start": 759.06, "end": 759.95, "text": "उसने बताया,", "who": "", "voice": "narrator", "diary": false}, {"start": 759.95, "end": 765.97, "text": "वो बचपन से इन पहाड़ों में एक्सपीडिशन्स के लिए कुक और बोझ उठाने वाला रहा है।", "who": "", "voice": "narrator", "diary": false}, {"start": 765.97, "end": 773.28, "text": "जब गब्बर ने बताया कि हम आगे कहाँ जा रहे हैं, दोरजे ने क्षितिज पर चमकती दूर की चोटी को देखा,", "who": "", "voice": "narrator", "diary": false}, {"start": 773.28, "end": 778.18, "text": "नंदा देवी, सबसे ऊँची, सबसे ख़ूबसूरत, और लगभग अपने आप से बोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 778.63, "end": 779.96, "text": "मैं गया था वहाँ।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 779.96, "end": 780.88, "text": "छियासठ में।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 780.88, "end": 782.04, "text": "बीस साल का था।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 782.74, "end": 784.17, "text": "उन्नीस सौ छियासठ।", "who": "", "voice": "narrator", "diary": false}, {"start": 784.87, "end": 786.63, "text": "मैंने साँस नहीं ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 787.33, "end": 788.32, "text": "एक टीम गई थी।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 788.52, "end": 791.38, "text": "उसने आगे कहा, हमसे ज़्यादा पहाड़ से।", "who": "", "voice": "narrator", "diary": false}, {"start": 791.58, "end": 793.6, "text": "अंग्रेज़ और हिंदुस्तानी।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 793.6, "end": 794.53, "text": "कुछ ढूँढने।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 794.53, "end": 796.3, "text": "हमें नहीं बताया क्या।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 796.3, "end": 800.44, "text": "बस इतना कहा: एक बॉक्स है, गरम होगा, हाथ मत लगाना।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 800.44, "end": 802.21, "text": "हम कई दिन ढूँढते रहे।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 802.21, "end": 803.39, "text": "कुछ नहीं मिला।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 803.59, "end": 805.27, "text": "उसने चाय की चुस्की ली।", "who": "", "voice": "narrator", "diary": false}, {"start": 805.47, "end": 808.58, "text": "रात को डेरे में एक साब बात कर रहे थे।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 808.58, "end": 811.94, "text": "बोल रहे थे: हो सकता है, बर्फ़ उसे खा गई।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 811.94, "end": 816.31, "text": "वो गरम है, तो बर्फ़ पिघलाता जाएगा… और नीचे, और नीचे।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 816.76, "end": 818.81, "text": "सूरज हमारे पीछे ढल रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 818.81, "end": 823.46, "text": "नंदा देवी की बर्फ़ सोने से गुलाबी, और गुलाबी से ग्रे हो गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 823.91, "end": 824.57, "text": "अगले साल।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 824.77, "end": 825.57, "text": "दोरजे ने कहा,", "who": "", "voice": "narrator", "diary": false}, {"start": 825.77, "end": 830.3, "text": "दूसरे पहाड़ पे, नंदा कोट पे, उन्होंने ऐसा एक और रखा था।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 830.3, "end": 834.67, "text": "फिर लाने गए, तो वो बर्फ़ में एक गुफ़ा बना के बैठा था।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 834.67, "end": 836.89, "text": "चारों तरफ़ बर्फ़ पिघली हुई।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 836.89, "end": 837.22, "text": "गरम।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 837.22, "end": 838.79, "text": "साल भर बाद भी… गरम।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 839.24, "end": 843.19, "text": "उसने अपने फ़्लास्क का ढक्कन वापस कसा, और मेरी तरफ़ मुड़ा,", "who": "", "voice": "narrator", "diary": false}, {"start": 843.19, "end": 847.0, "text": "जैसे उसे पता हो कि हममें से किसे ये सुनने की ज़रूरत है।", "who": "", "voice": "narrator", "diary": false}, {"start": 847.45, "end": 849.86, "text": "वो पहाड़ कुछ रखता है, बेटा।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 849.86, "end": 851.73, "text": "उसे जगाना नहीं चाहिए।", "who": "दोरजे", "voice": "dorje", "diary": false}, {"start": 852.18, "end": 859.49, "text": "फिर वो उठा, हमें सिर हिलाकर अलविदा कहा, और शाम के धुँधलके में नीचे उतरने लगा,", "who": "", "voice": "narrator", "diary": false}, {"start": 859.49, "end": 863.28, "text": "धीरे, और स्थिर क़दमों से: एक बूढ़ा आदमी,", "who": "", "voice": "narrator", "diary": false}, {"start": 863.28, "end": 866.89, "text": "जो साठ साल से इन पहाड़ों पर चल रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 868.39, "end": 872.36, "text": "उसके जाने के बहुत देर बाद तक, हम चंद्रशिला पर बैठे रहे।", "who": "", "voice": "narrator", "diary": false}, {"start": 872.36, "end": 877.56, "text": "तारे निकल आए, इतने तारे, जितने मैंने अपनी पूरी ज़िंदगी में नहीं देखे थे,", "who": "", "voice": "narrator", "diary": false}, {"start": 877.56, "end": 880.37, "text": "इतने, कि आसमान भीड़-भाड़ वाला लगने लगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 880.82, "end": 883.17, "text": "मैंने वही किया, जो मैं करता हूँ।", "who": "", "voice": "narrator", "diary": false}, {"start": 883.17, "end": 884.86, "text": "मैंने अपना लैपटॉप खोला।", "who": "", "voice": "narrator", "diary": false}, {"start": 884.86, "end": 887.5, "text": "हर डॉक्यूमेंट पढ़ा, जो मुझे मिल सका,", "who": "", "voice": "narrator", "diary": false}, {"start": 887.5, "end": 889.92, "text": "हर डीक्लासिफ़ाइड पेज, हर आर्टिकल।", "who": "", "voice": "narrator", "diary": false}, {"start": 889.92, "end": 892.27, "text": "मैंने हाफ़-लाइव्ज़ कैलकुलेट कीं।", "who": "", "voice": "narrator", "diary": false}, {"start": 892.27, "end": 898.73, "text": "मैं न्यूक्लियर फ़िज़िसिस्ट नहीं हूँ, लेकिन मुझे पढ़ना आता है, और नंबर्स चेक करना आता है,", "who": "", "voice": "narrator", "diary": false}, {"start": 898.73, "end": 903.35, "text": "और नंबर्स ये कह रहे थे: उस डिवाइस में जिस तरह का प्लूटोनियम है,", "who": "", "voice": "narrator", "diary": false}, {"start": 903.35, "end": 906.43, "text": "वो बहुत, बहुत लंबे समय तक ख़तरनाक रहता है।", "who": "", "voice": "narrator", "diary": false}, {"start": 906.43, "end": 909.07, "text": "हममें से किसी की भी ज़िंदगी से लंबा।", "who": "", "voice": "narrator", "diary": false}, {"start": 909.07, "end": 910.32, "text": "गीतों से भी लंबा।", "who": "", "voice": "narrator", "diary": false}, {"start": 910.77, "end": 912.45, "text": "रोहन ख़ज़ाना नहीं ढूँढ रहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 912.65, "end": 914.42, "text": "आख़िरकार मैंने कहा।", "who": "", "voice": "narrator", "diary": false}, {"start": 914.42, "end": 918.25, "text": "उस सारे सन्नाटे में, मेरी आवाज़ अजीब लगी।", "who": "", "voice": "narrator", "diary": false}, {"start": 918.7, "end": 920.77, "text": "शाओनी ने चोटी से नज़र नहीं हटाई।", "who": "", "voice": "narrator", "diary": false}, {"start": 920.97, "end": 922.85, "text": "वो प्लूटोनियम ढूँढ रहा है।", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 923.3, "end": 924.16, "text": "और बेचेगा।", "who": "", "voice": "narrator", "diary": false}, {"start": 924.61, "end": 925.07, "text": "किसको?", "who": "शाओनी", "voice": "shaoni", "diary": false}, {"start": 925.52, "end": 927.27, "text": "मैंने उसे जवाब नहीं दिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 927.27, "end": 929.1, "text": "कोई भी जवाब अच्छा नहीं था।", "who": "", "voice": "narrator", "diary": false}, {"start": 929.55, "end": 934.27, "text": "क्षितिज अपने फ़ोन की रोशनी में, बहुत धीरे-धीरे लिख रहा था।", "who": "", "voice": "narrator", "diary": false}, {"start": 934.27, "end": 938.25, "text": "जब उसने ख़त्म किया, तो उसे ज़ोर से पढ़ा, वैसे ही,", "who": "", "voice": "narrator", "diary": false}, {"start": 938.25, "end": 943.05, "text": "जैसे वो चीज़ें पढ़ता है, जब उसे पक्का करना हो कि वो सच हैं।", "who": "", "voice": "narrator", "diary": false}, {"start": 943.5, "end": 945.29, "text": "ग्लेशियर पिघल रहा है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 945.29, "end": 946.65, "text": "हर साल थोड़ा और।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 946.65, "end": 949.72, "text": "जो चीज़ साठ साल से बर्फ़ में सोई है…", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 950.42, "end": 950.98, "text": "वो रुका।", "who": "", "voice": "narrator", "diary": false}, {"start": 951.68, "end": 952.97, "text": "… वो जाग रही है।", "who": "क्षितिज", "voice": "kshitij", "diary": false}, {"start": 953.42, "end": 957.43, "text": "हमारे ऊपर, आख़िरी रोशनी नंदा देवी से चली गई।", "who": "", "voice": "narrator", "diary": false}, {"start": 957.43, "end": 964.35, "text": "कहीं नीचे, एक गाँव में, जो हमें दिख नहीं रहा था, पांडव लीला के ढोल बजते रहे,", "who": "", "voice": "narrator", "diary": false}, {"start": 964.35, "end": 969.36, "text": "बजते रहे, एक पुराने हीरो को दुनिया में वापस बुलाते हुए।", "who": "", "voice": "narrator", "diary": false}, {"start": 969.81, "end": 973.25, "text": "मेरी जेब में, मेरा फ़ोन एक बार बजा।", "who": "", "voice": "narrator", "diary": false}, {"start": 973.7, "end": 974.58, "text": "अननोन नंबर।", "who": "", "voice": "narrator", "diary": false}, {"start": 974.58, "end": 980.7, "text": "एक फ़ोटोग्राफ़: मेरी अपनी नोटबुक का एक पेज, वही, जो रोहन सवॉय में ले गया था,", "who": "", "voice": "narrator", "diary": false}, {"start": 980.7, "end": 984.24, "text": "जिस पर मेरी लिखावट में एक फ़ोन नंबर लिखा था,", "who": "", "voice": "narrator", "diary": false}, {"start": 984.24, "end": 986.26, "text": "और उसके बग़ल में एक शब्द।", "who": "", "voice": "narrator", "diary": false}, {"start": 986.96, "end": 987.33, "text": "मम्मी।", "who": "", "voice": "narrator", "diary": false}, {"start": 988.03, "end": 989.86, "text": "नंबर पर गोला बना था।", "who": "", "voice": "narrator", "diary": false}, {"start": 989.86, "end": 990.5, "text": "दो बार।", "who": "", "voice": "narrator", "diary": false}, {"start": 991.2, "end": 991.75, "text": "नीचे:", "who": "", "voice": "narrator", "diary": false}, {"start": 992.45, "end": 993.24, "text": "संडे।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 993.24, "end": 993.87, "text": "औली।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 993.87, "end": 994.81, "text": "अकेले।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 994.81, "end": 995.28, "text": "आर।", "who": "रोहन", "voice": "rohan", "diary": false}, {"start": 995.98, "end": 997.47, "text": "मैंने कोई जोक नहीं मारा।", "who": "", "voice": "narrator", "diary": false}, {"start": 997.47, "end": 998.83, "text": "क्षितिज ने नोटिस किया।", "who": "", "voice": "narrator", "diary": false}, {"start": 998.83, "end": 1000.06, "text": "उसने वो भी लिख लिया।", "who": "", "voice": "narrator", "diary": false}, {"start": 1000.51, "end": 1002.43, "text": "क्षितिज की डायरी से।", "who": "", "voice": "narrator", "diary": true}, {"start": 1002.43, "end": 1005.87, "text": "डे फ़ाइव, चोपता, तुंगनाथ, चंद्रशिला।", "who": "", "voice": "narrator", "diary": true}, {"start": 1006.32, "end": 1010.24, "text": "किडनैपिंग रिपोर्ट: मोज़े वाली रसीद देखो।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1010.24, "end": 1011.32, "text": "नंबर प्लेट।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1011.32, "end": 1012.59, "text": "बूट्स और गाद।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1012.59, "end": 1015.24, "text": "ड्राइवर ने कहा, जोशीमठ पंप।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1015.24, "end": 1017.59, "text": "आर. का बेस: जोशीमठ, औली।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1017.59, "end": 1022.88, "text": "भल्ला कभी सोता नहीं, और बार-बार अँधेरे को चेक करता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1022.88, "end": 1023.86, "text": "तीन स्टार।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1024.31, "end": 1028.75, "text": "गोलू की गाड़ी चोपता रोड पर ऊपर आई, तुंगनाथ से नीचे नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1028.75, "end": 1033.74, "text": "टायरों पर लाल मिट्टी, उसी रंग की, जिस सड़क से वो मुझे ले गए थे।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1033.74, "end": 1036.19, "text": "गोलू ने झूठ बोला कि वो कहाँ था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1036.19, "end": 1039.99, "text": "या तो वो उनके साथ है, या वो उनका पीछा कर रहा था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1039.99, "end": 1044.59, "text": "दीदी कहती हैं: इनमें से एक सच है, और मुझे दोनों पसंद नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1045.04, "end": 1049.22, "text": "दोरजे ने उन्नीस सौ छियासठ की सर्च में बोझ उठाया था।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1049.22, "end": 1051.93, "text": "एक बॉक्स, गरम होगा, हाथ मत लगाना।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1051.93, "end": 1055.05, "text": "वो बर्फ़ पिघलाता है, और धँसता जाता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1055.05, "end": 1058.49, "text": "नंदा कोट वाला डिवाइस, उन्नीस सौ अड़सठ में,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1058.49, "end": 1062.35, "text": "पिघली बर्फ़ की एक गुफ़ा में मिला था, तब भी गरम।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1062.8, "end": 1067.29, "text": "उन्नीस सौ छियासठ वाले चरवाहे, प्रताप सिंह रावत और दो और,", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1067.29, "end": 1069.85, "text": "ज्येष्ठ में केदारनाथ गए: मई-जून।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1069.85, "end": 1073.46, "text": "सर्च टीम मई में ऊपर गई, और उसे कुछ नहीं मिला।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1073.46, "end": 1077.06, "text": "क्या चरवाहों ने उसे सर्च टीम से पहले देखा था?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1077.06, "end": 1079.39, "text": "क्या उन्होंने उसे… हिलाया था?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1079.84, "end": 1083.71, "text": "भल्ला और गाने: डे वन, बाँसुरी पर खाना बंद किया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1083.71, "end": 1085.68, "text": "डे टू, घाट पर होंठ हिले।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1085.68, "end": 1090.04, "text": "डे फ़ोर, एस-यू-वी में पहाड़ी गाने बंद किए: गाना नहीं।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1090.04, "end": 1092.19, "text": "उसे भूतों से डर नहीं लगता।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1092.19, "end": 1094.41, "text": "उसे… एक गाने से डर लगता है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1094.41, "end": 1095.4, "text": "कौन सा गाना?", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1095.85, "end": 1098.7, "text": "आर. ने मम्मी के नंबर पर गोला बनाया।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1098.7, "end": 1101.88, "text": "तब से पार्थ भाई ने एक भी जोक नहीं मारा।", "who": "क्षितिज", "voice": "kshitij", "diary": true}, {"start": 1101.88, "end": 1104.73, "text": "ये इस डायरी का सबसे डरावना क्लू है।", "who": "क्षितिज", "voice": "kshitij", "diary": true}], "scenes": [{"at": 19.66, "bed": "vigil"}, {"at": 87.49, "bed": "dawn"}, {"at": 123.2, "bed": "meadow"}, {"at": 216.0, "bed": "receipt"}, {"at": 360.58, "bed": "tender"}, {"at": 411.25, "bed": "suspicion"}, {"at": 499.35, "bed": "trek"}, {"at": 555.26, "bed": "legend"}, {"at": 661.88, "bed": "pandavlila"}, {"at": 719.22, "bed": "summit"}, {"at": 777.43, "bed": "dorje"}, {"at": 867.19, "bed": "stars"}, {"at": 999.31, "bed": "diary"}, {"at": 999.31, "bed": "diary"}], "hits": [{"at": 82.63, "fx": "ping"}, {"at": 119.13, "fx": "keys"}, {"at": 205.32, "fx": "sting_light"}, {"at": 412.3, "fx": "cardoor"}, {"at": 423.2, "fx": "golu"}, {"at": 482.15, "fx": "sting"}, {"at": 556.31, "fx": "bell"}, {"at": 716.37, "fx": "sting"}, {"at": 847.3, "fx": "sting"}, {"at": 951.53, "fx": "sting"}, {"at": 969.66, "fx": "ping"}, {"at": 986.81, "fx": "sting"}, {"at": 1095.7, "fx": "sting"}], "next": {"label": "एपिसोड 6", "en": "The Village That Never Forgave Hanuman", "hook": "एक गाँव, जिसने हनुमान को कभी माफ़ नहीं किया। और एक प्रोफ़ेसर, जिसे सॉरी कहना है।"}};
